-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per expense line on people's expense reports (not vendor bills). The person's own, or everyone's with ap.view. Voided reports are left out.
CREATE VIEW rpt.Expense
AS
SELECT
    l.Id AS ExpenseLineId,
    l.ExpenseDate AS ExpenseDate,
    b.PayeeUserId AS PersonId,
    u.DisplayName AS Person,
    ec.Name AS Category,
    l.Merchant AS Merchant,
    l.Description AS Description,
    l.Quantity AS Quantity,
    l.Amount AS Amount,
    l.IsBillable AS IsBillable,
    l.BillableAmount AS BillableAmount,
    p.ClientId AS ClientId,
    c.Name AS ClientName,
    l.ProjectId AS ProjectId,
    p.Name AS ProjectName,
    t.TaskKey AS TaskKey,
    b.BillNumber AS ReportNumber,
    bs.Name AS ReportStatus,
    bs.SystemCode AS ReportStatusCode,
    CONVERT(BIT, IIF(l.InvoiceEntryId IS NULL, 0, 1)) AS IsInvoiced
FROM ap.BillLine AS l
JOIN ap.Bill AS b ON b.TenantId = l.TenantId AND b.Id = l.BillId
JOIN lkp.BillStatus AS bs ON bs.TenantId = b.TenantId AND bs.Id = b.BillStatusId
JOIN lkp.ExpenseCategory AS ec ON ec.TenantId = l.TenantId AND ec.Id = l.ExpenseCategoryId
JOIN sec.AppUser AS u ON u.TenantId = b.TenantId AND u.Id = b.PayeeUserId
LEFT JOIN crm.ClientProject AS p ON p.TenantId = l.TenantId AND p.Id = l.ProjectId
LEFT JOIN crm.Client AS c ON c.TenantId = p.TenantId AND c.Id = p.ClientId
LEFT JOIN crm.ClientTask AS t ON t.TenantId = l.TenantId AND t.Id = l.TaskId
WHERE b.PayeeUserId IS NOT NULL AND b.VoidedAt IS NULL AND (b.PayeeUserId = CONVERT(INT, SESSION_CONTEXT(N'UserId')) OR EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(b.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'ap.view')));
GO
